/bin/zsh -lc "python -c 'import pandas as pd, numpy as np, json; from scipy.stats import norm; from itertools import combinations
x=pd.read_csv(\"respondents.csv\"); cs=[\"Flex\",\"Plus\",\"Simple\"]; pairs=list(combinations(cs,2)); outcomes=[\"appeal_5\",\"purchase_intent_5\",\"uniqueness_5\",\"relevance_5\",\"credibility_5\",\"value_5\",\"understanding_5\"]
def stat(d,q):
 d=d[d[q].notna()]; w=d.wt_final.to_numpy(); y=d[q].ge(4).to_numpy(); p=np.average(y,weights=w); v=len(d)/(len(d)-1)*sum(w*w*(y-p)**2)/sum(w)**2
 return dict(n=len(d),ws=round(sum(w),3),neff=round(sum(w)**2/sum(w*w),1),dist=[round(100*np.average(d[q].eq(i),weights=w),2) for i in range(1,6)],t2=round(p*100,4)),p,v
def holm(ps):
 ix=np.argsort(ps); out=np.zeros(len(ps)); run=0
 for j,i in enumerate(ix):
  run=max(run,min(1,ps[i]*(len(ps)-j))); out[i]=run
 return out.tolist()
def comparisons(s):
 r=[]; ps=[]
 for a,b in pairs:
  dif=s[a][1]-s[b][1]; se=np.sqrt(s[a][2]+s[b][2]); ps.append(2*norm.sf(abs(dif/se))); r.append(dict(pair=a+\"-\"+b,diff=round(100*dif,4),ci=[round(100*(dif-1.95996398454*se),4),round(100*(dif+1.95996398454*se),4)]))
 for row,p in zip(r,holm(ps)): row[\"p_holm\"]=p
 return r
for name,d,qs in [(\"overall\",x,outcomes),(\"explorer\",x[x.food_explorer.eq(1)],outcomes[:2]),(\"nonexplorer\",x[x.food_explorer.eq(0)],outcomes[:2]),(\"premium\",x,[\"premium_value_5\"])]:
 for q in qs:
  s={c:stat(d[d.concept.eq(c)],q) for c in cs}; print(json.dumps(dict(group=name,q=q,cells={c:s[c][0] for c in cs},comparisons=comparisons(s))))
for q in outcomes[:2]:
 s={c: (None,stat(x[x.concept.eq(c)&x.food_explorer.eq(1)],q)[1]-stat(x[x.concept.eq(c)&x.food_explorer.eq(0)],q)[1],stat(x[x.concept.eq(c)&x.food_explorer.eq(1)],q)[2]+stat(x[x.concept.eq(c)&x.food_explorer.eq(0)],q)[2]) for c in cs}; print(\"interaction\",q,json.dumps(comparisons(s)))
print(\"explorer share\",100*x.loc[x.food_explorer.eq(1),\"wt_final\"].sum()/x.wt_final.sum())
for c in cs:
 d=x[x.concept.eq(c)]; print(\"diagnostics\",c,{q:round(np.average(d[q],weights=d.wt_final)*100,2) for q in x.columns if q.startswith((\"like_\",\"dislike_\"))}); print(\"eligible\",c,100*d.loc[d.understanding_5.ge(3),\"wt_final\"].sum()/d.wt_final.sum())'"

